/* ============================================================
   MEETS
   ============================================================ */
/* Log one lift or several — whatever actually got tested. Blank rows are
   skipped, so a squat-only day is a first-class entry, not a partial one. */
/* Tests are the big three only — squat, bench, deadlift — pinned to the
   priority-lift variants, so the rows are fixed rather than picked. (0.16.3:
   the old picker preselected by name against key-valued options, so every row
   fell back to the first barbell lift, and the entries it sent carried no leaf,
   so logTest filtered all of them out and nothing could ever save.) */
const TEST_FALLBACK = { squat: 'Back Squat', bench: 'Bench Press', deadlift: 'Deadlift' };
function testRows() {
  return EVENT_TYPES[DEFAULT_EVENT_TYPE].lifts.map(l => {
    const leaf = priorityLeaf(l.slot) || leafForName(TEST_FALLBACK[l.slot] || l.label);
    return { slot: l.slot, label: l.label, leaf, name: displayName(leaf) };
  });
}
export function openTestLog() {
  const rows = testRows();
  modal({
    title: 'Log a test',
    body: `
      <p class="sub" style="margin-top:0">Enter what you actually tested and leave the rest blank. Each one logs as a true single, so it replaces the estimate for that lift.</p>
      <div class="field"><label>Date</label><input type="date" id="tDate" value="${today()}"></div>
      ${rows.map((r, i) => `
        <div class="field"><label>${esc(r.label)} <span class="dimmer">${esc(r.name)}</span></label>
          <input type="number" step="0.5" min="0" inputmode="decimal" id="tKg${i}" placeholder="${U()}"></div>`).join('')}
      <div class="field"><label>Notes (optional)</label><input id="tNote" placeholder="kit, commands, how it moved"></div>
    `,
    foot: `<button class="btn primary" id="tSave">Save test</button>`,
    onOpen: bg => {
      $('#tSave', bg).onclick = () => {
        const date = $('#tDate', bg).value || today();
        const entries = rows.map((r, i) => ({
          leaf: r.leaf,
          kg: toKg(parseFloat(String($(`#tKg${i}`, bg).value).replace(',', '.')) || 0),
        }));
        const n = logTest(date, entries, $('#tNote', bg).value.trim());
        if (!n) return toast('Enter a weight for at least one lift');
        closeAllModals(); render();
        toast(`${n} lift${n === 1 ? '' : 's'} tested — openers updated`, 'green');
      };
    },
  });
}

/* ---------------- placing predictor ----------------
   Field data: 2025 EPA West Midlands Spring Championship, Men's 93kg Classic
   Raw, via the OpenPowerlifting project (public domain, attribution kept).
   One year is a small sample — a single strong entry shifts everything under
   it — so this is a range, not a promise. */
/* Events saved before types existed are powerlifting meets — no migration
   needed, the default covers them. */
export function eventType(m) {
  return EVENT_TYPES[(m && m.type) || DEFAULT_EVENT_TYPE] || EVENT_TYPES[DEFAULT_EVENT_TYPE];
}
/* The type supplies the lifts; an event may carry its own, which is how a
   single-lift meet says which lift it actually contests. */
function eventLifts(m) {
  if (m && Array.isArray(m.lifts$) && m.lifts$.length) return m.lifts$;
  return eventType(m).lifts;
}

/* Which leaf a contested lift means for YOU. Your own choice for that slot wins
   — an IPF squat is whatever you compete with — and otherwise it falls back to
   the movement the type names. Resolving by movement rather than by position in
   settings.priority is what lets a discipline contest a lift that is not one of
   your three, like the strengthlifting press. */
function liftKey(lift) {
  const p = priorityLeaf(lift.slot);
  if (p) return leafKey(p);
  const mv = movementById(lift.movement);
  if (!mv) return '';
  return leafKey(completeLeaf(mv, { equipment: lift.equipment }));
}
function liftBest(lift) { return latestTest(liftKey(lift)); }
function eventTypeList() { return Object.values(EVENT_TYPES); }

